import java.io.*;

public class Main {
    private static final InputStream IN = System.in;
    private static final byte[] BUF = new byte[1 << 16];
    private static int len = 0, ptr = 0;

    private static int read() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    private static int skipSpaces() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        return c;
    }

    private static long nextLong() throws IOException {
        int c = skipSpaces();
        boolean negative = c == '-';
        if (negative) c = read();
        long value = 0;
        while (c >= '0' && c <= '9') {
            value = value * 10 + (c - '0');
            c = read();
        }
        return negative ? -value : value;
    }

    private static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), k = nextInt();
        long p = nextLong();
        // ends[j]: coverage that stops applying at chapter j (difference array).
        long[] ends = new long[n + 1];
        long active = 0, answer = 0;
        for (int i = 0; i < n; i++) {
            long v = nextLong();
            active -= ends[i];
            long need = (v + p - 1) / p;
            if (need > active) {
                // Add the missing coverage with the rightmost window that still contains chapter i.
                long delta = need - active;
                answer += delta;
                active += delta;
                int start = Math.min(i, n - k);
                ends[start + k] += delta;
            }
        }
        System.out.println(answer);
    }
}

package main

import (
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

// next returns the next whitespace-separated token of the input.
func next() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	token := next()
	negative := len(token) > 0 && token[0] == '-'
	if negative {
		token = token[1:]
	}
	value := 0
	for _, c := range token {
		value = value*10 + int(c-'0')
	}
	if negative {
		return -value
	}
	return value
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, k, p := nextInt(), nextInt(), nextInt()
	// ends[j]: coverage that stops applying at chapter j (difference array).
	ends := make([]int, n+1)
	active, answer := 0, 0
	for i := 0; i < n; i++ {
		v := nextInt()
		active -= ends[i]
		need := (v + p - 1) / p
		if need > active {
			// Add the missing coverage with the rightmost window that still contains chapter i.
			delta := need - active
			answer += delta
			active += delta
			start := min(i, n-k)
			ends[start+k] += delta
		}
	}
	os.Stdout.WriteString(strconv.Itoa(answer) + "\n")
}
